# Check coder session parents/origins - look at task content for clues
python3 -c "
import json, os
from collections import Counter

hist = '.state/sessions/history/'
cutoff = 1774233569795 - 46800000  # 13h ago

task_types = Counter()
for sid in os.listdir(hist):
    meta_path = os.path.join(hist, sid, 'meta.json')
    if not os.path.exists(meta_path):
        continue
    try:
        with open(meta_path) as f:
            meta = json.load(f)
    except:
        continue
    if meta.get('startedAt', 0) < cutoff:
        continue
    if meta.get('agent') != 'coder':
        continue

    task = meta.get('task', '')

    # Categorize by task content
    if 'payment service' in task.lower():
        task_types['payment-service-fix'] += 1
    elif 'process-pipeline' in task.lower():
        task_types['process-pipeline'] += 1
    elif 'config.json' in task.lower() or 'configuration file' in task.lower():
        task_types['config-json-fix'] += 1
    elif 'process.js' in task.lower():
        task_types['process-js-fix'] += 1
    elif 'test coverage' in task.lower():
        task_types['test-coverage'] += 1
    elif 'Phase 1' in task:
        task_types['two-phase-analysis'] += 1
    elif 'Phase 2' in task:
        task_types['two-phase-fix'] += 1
    else:
        task_types[task[:50]] += 1

print('Coder task categories:')
for task_type, count in task_types.most_common():
    print(f'  {count:>3}x  {task_type}')
print()
print(f'Total: {sum(task_types.values())}')
" 2>/dev/null

