python3 -c "
import json, os
from collections import Counter

hist = '.state/sessions/history/'
cutoff = 1774233569795 - 46800000

# Track ALL file reads (both read() and bash cat) per agent
agent_file_reads = {}  # agent -> Counter of file paths

for sid in os.listdir(hist):
    meta_path = os.path.join(hist, sid, 'meta.json')
    if not os.path.exists(meta_path):
        continue
    try:
        with open(meta_path) as f:
            meta = json.load(f)
    except:
        continue
    if meta.get('startedAt', 0) < cutoff:
        continue

    agent = meta.get('agent', 'unknown')
    if agent not in agent_file_reads:
        agent_file_reads[agent] = Counter()

    session_path = os.path.join(hist, sid, 'session.jsonl')
    if not os.path.exists(session_path):
        continue

    with open(session_path) as f:
        for line in f:
            try:
                d = json.loads(line.strip())
                if d.get('role') != 'assistant':
                    continue
                content = d.get('content', [])
                if not isinstance(content, list):
                    continue
                for item in content:
                    if item.get('type') != 'toolCall':
                        continue
                    name = item.get('name', '')
                    args = item.get('arguments', {})

                    if name == 'read':
                        path = args.get('path', '')
                        agent_file_reads[agent][path] += 1
            except:
                pass

# Find files read by multiple agents or read repeatedly
print('=== Repeated File Reads by Agent (>3x) ===')
for agent in sorted(agent_file_reads.keys()):
    counter = agent_file_reads[agent]
    repeated = [(path, count) for path, count in counter.items() if count > 3]
    if repeated:
        print(f'\n{agent}:')
        for path, count in sorted(repeated, key=lambda x: -x[1]):
            print(f'  {count:>3}x  {path}')

# Cross-agent: which files are read by the most agents?
print('\n=== Files Read by Multiple Agents ===')
file_agents = Counter()
for agent, counter in agent_file_reads.items():
    for path in counter:
        file_agents[path] += 1

multi_agent_files = [(path, count) for path, count in file_agents.items() if count >= 3]
for path, agent_count in sorted(multi_agent_files, key=lambda x: -x[1]):
    total_reads = sum(agent_file_reads[a].get(path, 0) for a in agent_file_reads)
    agents = [a for a in agent_file_reads if path in agent_file_reads[a]]
    print(f'  {agent_count} agents, {total_reads:>3} reads: {path}')
    print(f'    agents: {agents}')
" 2>/dev/null

